import torch
from clharness.train.hooks import BaseHook

class BoundaryBasisInertia(BaseHook):
    def on_domain_start(self, ctx, domain):
        self.domain_count = getattr(self, 'domain_count', 0) + 1
        self.active = self.domain_count > 1
        self.factors = []
        self.previous = []
        if self.active:
            for name, parameter in ctx.model.named_parameters():
                if parameter.requires_grad and 'lora_a' in name.lower():
                    self.factors.append(parameter)
                    self.previous.append(parameter.detach().clone())

    @torch.no_grad()
    def on_step_end(self, ctx, stats):
        if getattr(self, 'active', False):
            for parameter, previous in zip(self.factors, self.previous):
                parameter.lerp_(previous, 0.875)
                previous.copy_(parameter)

import torch
from clharness.train.hooks import BaseHook

class BoundaryGaugeBalance(BaseHook):
    def on_run_start(self, ctx):
        self.domain_count = 0

    @torch.no_grad()
    def on_domain_start(self, ctx, domain):
        self.domain_count += 1
        if self.domain_count != 2:
            return
        parameters = dict(ctx.model.named_parameters())
        for name, a in parameters.items():
            if 'lora_A' not in name or a.ndim != 2:
                continue
            partner = name.replace('lora_A', 'lora_B')
            if partner not in parameters:
                continue
            b = parameters[partner]
            if b.ndim != 2:
                continue
            an = a.float().norm()
            bn = b.float().norm()
            if an.item() <= 1e-12 or bn.item() <= 1e-12:
                continue
            scale = (bn / an).sqrt().clamp(0.25, 4.0).item()
            a.mul_(scale)
            b.div_(scale)

import torch
from clharness.train.hooks import BaseHook

class BoundaryModeBalance(BaseHook):
    def on_run_start(self, ctx):
        self.domain_count = 0

    @torch.no_grad()
    def on_domain_start(self, ctx, domain):
        self.domain_count += 1
        if self.domain_count != 2:
            return
        parameters = dict(ctx.model.named_parameters())
        for name, a in parameters.items():
            if 'lora_A' not in name or a.ndim != 2:
                continue
            partner = name.replace('lora_A', 'lora_B')
            if partner not in parameters:
                continue
            b = parameters[partner]
            if b.ndim != 2:
                continue
            rank = a.shape[0]
            if b.shape[1] != rank or a.shape[1] < rank or b.shape[0] < rank:
                continue
            qa, ra = torch.linalg.qr(a.float().T, mode='reduced')
            qb, rb = torch.linalg.qr(b.float(), mode='reduced')
            u, s, vh = torch.linalg.svd(rb @ ra.T, full_matrices=False)
            root = s.clamp_min(0).sqrt()
            balanced_a = root[:, None] * (vh @ qa.T)
            balanced_b = (qb @ u) * root[None, :]
            a.copy_(balanced_a.to(dtype=a.dtype))
            b.copy_(balanced_b.to(dtype=b.dtype))

import torch
import math
from clharness.train.hooks import BaseHook

class CodeConflictRedistribution(BaseHook):
    def on_run_start(self, ctx):
        self.finished = 0
        self.code = {}

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        self.finished += 1
        parameters = dict(ctx.model.named_parameters())
        if self.finished == 1:
            for name, a in parameters.items():
                if 'lora_A' not in name or a.ndim != 2:
                    continue
                partner = name.replace('lora_A', 'lora_B')
                if partner not in parameters:
                    continue
                b = parameters[partner]
                if b.ndim == 2 and b.shape[1] == a.shape[0]:
                    self.code[name] = (a.detach().clone(), b.detach().clone())
            return
        if self.finished != 2:
            return
        records = []
        for name, saved in self.code.items():
            partner = name.replace('lora_A', 'lora_B')
            a = parameters[name].float()
            b = parameters[partner].float()
            ca = saved[0].float()
            cb = saved[1].float()
            energy = ((b.T @ b) * (a @ a.T)).sum().clamp_min(0).item()
            code_energy = ((cb.T @ cb) * (ca @ ca.T)).sum().clamp_min(0).item()
            inner = ((b.T @ cb) * (a @ ca.T)).sum().item()
            legal_energy = max(energy + code_energy - 2.0 * inner, 0.0)
            denominator = math.sqrt(max(code_energy * legal_energy, 1e-30))
            score = (inner - code_energy) / denominator
            records.append((score, name, energy))
        if len(records) < 2:
            return
        records.sort()
        split = len(records) // 2
        selected = set()
        reduced_energy = 0.0
        remaining_energy = 0.0
        for index, record in enumerate(records):
            if index < split:
                selected.add(record[1])
                reduced_energy += record[2]
            else:
                remaining_energy += record[2]
        if remaining_energy <= 1e-20:
            return
        compensation = math.sqrt((remaining_energy + 0.75 * reduced_energy) / remaining_energy)
        for record in records:
            name = record[1]
            partner = name.replace('lora_A', 'lora_B')
            factor = 0.5 if name in selected else compensation
            parameters[partner].mul_(factor)

import torch
from clharness.train.hooks import BaseHook

class CodeDirectionRotation(BaseHook):
    def on_run_start(self, ctx):
        self.finished = 0
        self.code = {}

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        self.finished += 1
        parameters = dict(ctx.model.named_parameters())
        if self.finished == 1:
            for name, a in parameters.items():
                if 'lora_A' not in name or a.ndim != 2:
                    continue
                partner = name.replace('lora_A', 'lora_B')
                if partner not in parameters:
                    continue
                b = parameters[partner]
                if b.ndim == 2 and b.shape[1] == a.shape[0]:
                    self.code[name] = (a.detach().clone(), b.detach().clone())
            return
        if self.finished != 2:
            return
        for name, saved in self.code.items():
            partner = name.replace('lora_A', 'lora_B')
            a = parameters[name]
            b = parameters[partner]
            if a.shape[1] < a.shape[0]:
                continue
            q, r = torch.linalg.qr(a.float().T, mode='reduced')
            current = b.float() @ r.T
            code_projected = saved[1].float() @ (saved[0].float() @ q)
            current_norm = current.norm()
            code_norm = code_projected.norm()
            if current_norm.item() <= 1e-12 or code_norm.item() <= 1e-12:
                continue
            rotated = 0.75 * current + 0.25 * (current_norm / code_norm) * code_projected
            rotated_norm = rotated.norm()
            if rotated_norm.item() <= 1e-12:
                continue
            rotated.mul_(current_norm / rotated_norm)
            a.copy_(q.T.to(dtype=a.dtype))
            b.copy_(rotated.to(dtype=b.dtype))
